$('.brand span').textContent=appVersion==='0.0.0'?'v0.0':appVersion;
function notify(message,error=false){$('#status').textContent=message;const t=$('#toast');t.textContent=message;t.className=error?'error':'';t.hidden=false;clearTimeout(t.timer);t.timer=setTimeout(()=>t.hidden=true,error?10000:4000);}
async function attempt(fn){try{return await fn();}catch(e){console.error(e);notify(e.message||String(e),true);}}
function desktop(){if(!api)throw Error('Local engine and asset operations require the Fusion desktop app.');}
function modal(title,body,footer=''){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><span class="eyebrow">FUSION STUDIO</span><h2>${esc(title)}</h2></div>${btn('close-modal','Close dialog','x')}</header><div class="modal-body">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;$('#close-modal').onclick=closeModal;iconsNow();$('#close-modal').focus();}
function closeModal(){const dismiss=modalDismiss;modalDismiss=null;dismiss?.();$('#modal-root').replaceChildren();if(editor)$('#editor-mode').value=editor.meshTools.mode;}
function setBusy(value,text='Processing…'){busy=value;updateCancelButton();$('#app').classList.toggle('busy',value);$('#status').textContent=value?text:'Ready';document.querySelectorAll('[data-job],#render,#export,#import-model,[data-load-asset],#simulate-cloth,#apply-native').forEach(b=>b.disabled=value);if(editor)editor.transform.enabled=!value&&!operators?.running&&!editor.weightPaint?.active;if(value)editor.timeline.playing=false;}
let canceling=false;
function updateCancelButton(){const button=$('#cancel-operation');if(!button)return;button.hidden=!(busy||operators?.running||canceling);button.disabled=canceling;button.textContent=canceling?'Stopping…':'Cancel';}
async function cancelOperation(){if(canceling||(!busy&&!operators?.running))return;canceling=true;updateCancelButton();operators?.cancel();try{await api.cancel();}finally{canceling=false;updateCancelButton();}}
$('#cancel-operation').onclick=()=>attempt(cancelOperation);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&editor?.creatorShapeSession&&!operators?.running){e.preventDefault();e.stopImmediatePropagation();attempt(()=>operators.run('character.creator_shape_cancel'));}},true);
function range(id,label,value,min,max,step='.01',unit=''){return `<label class="slider-label" for="${id}">${label}<output>${Number(value).toFixed(step==='1'?0:2)}${unit}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}">`;}
function section(title,content){return `<section class="library-section"><div class="section-heading"><span>${title}</span></div>${content}</section>`;}

function compatibility(action,object,run,context={}){
  const stats=inspectObject(object),report=checkCompatibility(action,stats,context);
  if(!report.issues.length)return Promise.resolve(run(false));
  return new Promise(resolve=>{
    const canStatic=(stats.skinned>0||stats.morphs>0)&&[...modifiers,'edit','sculpt','extrude','delete-face'].includes(action)&&!report.issues.some(i=>i.severity==='block'&&i.title!=='Rig or morph data can be lost');
    modalDismiss=()=>resolve(null);
    modal('Mesh compatibility — '+action,`<div class="compat-summary">${icon('triangle-alert')}Check this before processing your mesh.</div><ul class="compat-issues">${report.issues.map(i=>`<li class="${i.severity}"><strong>${esc(i.title)}</strong><p>${esc(i.detail)}</p></li>`).join('')}</ul><p class="description">Cancel keeps the scene as it is. A working copy preserves the source object and its controls.</p>`,`<button id="compat-cancel" class="button subtle">Cancel</button>${canStatic?'<button id="compat-static" class="button accent">Make static copy & continue</button>':report.blocked?'':`<button id="compat-copy" class="button accent">${modifiers.includes(action)||['sculpt','extrude','delete-face','cloth'].includes(action)?'Use working copy':'Continue'}</button>`}`);
    $('#compat-cancel').onclick=()=>{closeModal();resolve(null);};$('#close-modal').onclick=()=>{closeModal();resolve(null);};
    $('#compat-static')?.addEventListener('click',()=>{modalDismiss=null;closeModal();resolve(run(false,context.deferStatic?'static':editor.staticDuplicate()));});
    $('#compat-copy')?.addEventListener('click',()=>{modalDismiss=null;closeModal();resolve(run(modifiers.includes(action)||['sculpt','extrude','delete-face','cloth'].includes(action)));});
  });
}
async function mode(value){if(value==='weights'){try{return await editor.weightPaint.start();}catch(error){$('#editor-mode').value=editor.meshTools.mode;throw error;}}if(editor.weightPaint?.active)editor.weightPaint.stop(false);if(!editor.selected&&value!=='object')throw Error('Select a mesh first.');const stack=editor.selected?.userData.modifierStack;if(stack&&value==='sculpt')throw Error('Apply the modifier stack before sculpting its evaluated surface. Retained source edits currently use Component Editing.');if(stack&&value==='edit'&&!stack.editSource)throw Error('Choose Edit retained source cage in the modifier stack first.');const set=()=>{editor.meshTools.setMode(value);$('#editor-mode').value=value;$('#mode-hint').textContent=modeHint(value);};if(value==='object')return set();await compatibility(value==='edit'?'extrude':'sculpt',editor.selected,(copy)=>{if(copy){const original=editor.selected;editor.duplicate(false);original.visible=false;editor.clearParametric(editor.selected);}set();});}

function activate(space){workspace=space;areas?.activate(space);document.querySelectorAll('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace===space));$('#context-title').textContent=space;$('#context-description').textContent=({Layout:'One scene for modeling, characters and clothing',Modeling:'Object transforms · face editing · mesh modifiers',Sculpting:'Shape the mesh with a live brush','UV Editing':'UV inspection and projection',Shading:'Materials and surface properties',Character:'Body proportions · FK / IK · skeleton',Clothing:'Polygon panels · sewing · cloth simulation',Animation:'Object and bone keyframes · playback',Rendering:'Render the scene from the current view',Assets:'Your installed libraries and created assets'})[space];$('#uv-overlay').hidden=space!=='UV Editing';if(space==='UV Editing')drawUV();library();properties();if(space==='Assets'&&!catalog.assets.length)attempt(scanAssets);}
