    $('#library').innerHTML=section('PANELS & SEWING',`<button id="pattern-designer" class="button import-button">${icon('scissors')}Pattern & Sewing Editor</button><p class="microcopy">Draw polygon panels, join edges, choose pins and fabric.</p>`)+(pattern?section('CURRENT PATTERN',`<p>${esc(selected.name)}</p><p class="microcopy">${pattern.panels.length} panels · ${pattern.seams.length} seams · ${esc(pattern.fabric)} fabric<br>${pattern.panels.map(p=>esc(p.name)).join(' / ')}</p><p class="microcopy">${selected.userData.liveGarment?'Linked drape. Edit original panels and apply to re-fit this garment.':selected.userData.simulationApplied?'Baked drape. Editing keeps this mesh and makes a new flat-pattern copy.':'Editable pattern panels. Open the editor to reshape or sew.'}</p>`):section('PATTERN DESIGN',`<select id="garment-type" aria-label="Garment type">${['skirt','tunic','cape'].map(t=>`<option value="${t}" ${params.type===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select><button id="create-pattern" class="button import-button">${icon('shirt')}Create pattern</button>${patternSVG(params)}${range('garment-width','Width',params.width,.25,1.1)}${range('garment-length','Length',params.length,.2,1.2)}${range('garment-flare','Flare',params.flare,0,.55)}${range('garment-ease','Body clearance',params.ease,.005,.15,'.005')}<label class="field-label">Fabric color<input id="fabric-color" type="color" value="${params.color}"></label>`))+section('CLOTH SIMULATION',`${range('cloth-frames','Frames',clothSettings.frames,10,120,'1')}${pattern?`<p class="microcopy">Uses the ${esc(pattern.fabric)} material preset chosen in the pattern editor.</p>`:range('cloth-stiffness','Stiffness',clothSettings.stiffness,1,60,'1')+range('cloth-mass','Vertex mass',clothSettings.mass,.05,1,'.05')}<button id="simulate-cloth" class="button import-button">${icon('play')}Simulate selected garment</button><p class="microcopy">${pattern?'Authored pins and seams':'Pinned top edge'} · gravity · body collision · self collision. Creates a baked mesh in this scene.</p>`);
