function poseControls(obj){const bones=[];obj?.traverse(n=>{if(n.isBone)bones.push(n);});if(!bones.length)return '<p class="microcopy">Select a rigged character to pose its joints.</p>';return `<label class="field-label">Joint</label><select id="pose-joint" aria-label="Pose joint">${bones.map(n=>`<option value="${n.uuid}" ${n.uuid===activeJoint?'selected':''}>${esc(n.name)}</option>`).join('')}</select>${['x','y','z'].map(a=>range('pose-'+a,'Rotate '+a.toUpperCase(),0,-150,150,'1','°')).join('')}`;}
function nativeValues(obj){return (obj.userData.dazNative.properties||[]).filter(p=>p.max>p.min&&(p.label+' '+p.name).toLowerCase().includes(nativeFilter.toLowerCase())).slice(0,24);}
function nativeControls(obj){const values=nativeValues(obj);return section('NATIVE SHAPING',`<input id="native-search" type="search" placeholder="Search shaping controls…" value="${esc(nativeFilter)}" aria-label="Search native shapes">${values.length?values.map((p,i)=>range('native-'+i,p.label||p.name,p.value,Math.max(-2,p.min),Math.min(2,p.max),'.01')).join(''):'<p class="microcopy">No matching referenced shaping properties. Use the rig or a static copy for mesh editing.</p>'}<p class="microcopy">Loaded shape targets respond directly in this scene. The import report records formula, HD and shader limits.</p>`);}
