    const whole=['cloth','boolean'].includes(action),data=await editor.glb(!whole,{includeAnimations:false}),r=await api.job({action,data,name:target.name,params:{...extra,targetId,...(action==='cloth'?{...clothSettings,...(target.userData.patternProject?{patternCloth:patternPayload(target)}:{})}:{})}});const group=await editor.importGLB(r.data,target.name,target);
      if(action==='cloth')group.userData={...target.userData,simulationApplied:true,source:'Simulated garment'};else group.userData.source='Fusion modeled mesh';editor.meshTools.setMode('object');editor.batching=false;editor.commit();notify(action==='cloth'?'Clothing simulation baked into your scene.':'Mesh operation applied.');if(action==='uv')drawUV();return r;
