async function conversionDialog(file,load){
  const extension=file.extension||file.name.slice(file.name.lastIndexOf('.'));
  const report=checkCompatibility('convert',{}, {extension});
  const native=extension==='.duf'?(file.id?await api.inspectAsset(file.id):await api.inspectFile(file.path)):null;
  let gltf;if(['.glb','.gltf'].includes(extension)){setBusy(true,'Inspecting glTF before import…');try{gltf=file.id?await api.inspectAsset(file.id):await api.inspectFile(file.path);}finally{setBusy(false);}if(gltf.blocked||!gltf.complete){modal('glTF Import Blocked',gltfReportHTML(gltf));return;}}
  if(native?.ok===false){modal('Native asset preflight failed',`<p>This asset cannot be reconstructed with the current reader. Nothing has been added to the scene.</p>${(native.errors||[]).map(e=>`<div class="notice"><p>${esc(e)}</p></div>`).join('')}`);return;}
  const warnings=native?.warnings||[];
  modal('Import Compatibility',`<div class="file-card">${icon('file-box')}<div><strong>${esc(file.name)}</strong><small>${esc(extension)} · source is read only</small></div></div>${gltf?gltfReportHTML(gltf):''}${report.issues.map(i=>`<div class="notice"><p><strong>${esc(i.title)}</strong><br>${esc(i.detail)}</p></div>`).join('')}${warnings.map(w=>`<div class="notice"><p>${esc(typeof w==='string'?w:JSON.stringify(w))}</p></div>`).join('')}${extension==='.blend'&&!file.id?'<label class="field-label">Blender import mode</label><select id="blend-mode"><option value="preserved">Preserve native rendering · evaluated viewport</option><option value="interchange">Editable mesh / rig interchange · approximate shading</option></select>':''}<label class="field-label">Source units</label><select id="import-scale" ${native?'disabled':''}><option value="1">${native?'DSON centimeters converted automatically':'Automatic / already meters'}</option><option value=".01">Raw centimeters to meters</option><option value=".001">Raw millimeters to meters</option><option value=".5">DAZ Blender OBJ preset (50 cm/unit)</option></select><p class="description">Rig and shader fidelity must be inspected in the working scene. Missing native engine adapters are shown before any conversion begins.</p>`,`<button class="button accent" id="confirm-import">Import working copy</button>`);
  $('#confirm-import').onclick=()=>attempt(async()=>{const scale=Number($('#import-scale').value),importOptions={...($('#blend-mode')?{blendMode:$('#blend-mode').value}:{}),...(gltf?{gltfHash:gltf.assetHash}:{})};closeModal();setBusy(true,'Loading model…');try{const r=await load(scale,importOptions);const group=await editor.importGLB(r.data,file.name.replace(/\.[^.]+$/,''));if(r.sourceCapsule)group.userData={...group.userData,sourceCapsule:r.sourceCapsule,...(file.path?{sourceOriginalPath:file.path}:{})};if(r.nativeBlend){attachNativeScene(group,r.nativeBlend);editor.commit();}if(r.native){group.userData={...group.userData,fusion_kind:'daz_character',dazNative:r.native,nativeSource:r.source};editor.commit();}const nativeWarnings=r.nativeBlend?.warnings||[];notify((r.sourceCapsule?`Working mesh loaded into Fusion. ${capsuleSummary(r.sourceCapsule)}`:'Working mesh loaded into Fusion.')+(nativeWarnings.length?` ${nativeWarnings.length} preservation warning${nativeWarnings.length>1?'s':''}: ${nativeWarnings[0]}`:''));}finally{setBusy(false);}});
}
