function drawUV(){const canvas=$('#uv-canvas');if(!canvas||!editor)return;canvas.width=500;canvas.height=500;const ctx=canvas.getContext('2d');ctx.fillStyle='#303030';ctx.fillRect(0,0,500,500);for(let x=0;x<10;x++)for(let y=0;y<10;y++){ctx.fillStyle=(x+y)%2?'#3d3d3d':'#353535';ctx.fillRect(x*50,y*50,50,50);}let mesh=null;editor.selected?.traverse(n=>{if(!mesh&&n.isMesh)mesh=n;});if(!mesh?.geometry.attributes.uv)return;const g=mesh.geometry,uv=g.attributes.uv,idx=g.index?.array||Array.from({length:uv.count},(_,i)=>i);ctx.strokeStyle='#dc952e';ctx.lineWidth=.6;for(let i=0;i<Math.min(idx.length,90000);i+=3){ctx.beginPath();for(let j=0;j<3;j++){const x=uv.getX(idx[i+j])*480+10,y=(1-uv.getY(idx[i+j]))*480+10;j?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.stroke();}}

