function operatorPreflight(op){
  if(!op.compatibility)return true;
  const report=checkCompatibility(op.compatibility,inspectObject(editor.selected));if(!report.issues.length)return true;
  return new Promise(resolve=>{
    modalDismiss=()=>resolve(false);
    modal('Operator compatibility',`<p>${esc(op.label)}</p><ul class="compat-issues">${report.issues.map(i=>`<li class="${i.severity}"><strong>${esc(i.title)}</strong><p>${esc(i.detail)}</p></li>`).join('')}</ul>`,`<button id="operator-cancel" class="button subtle">Cancel</button>${report.blocked?'':'<button id="operator-proceed" class="button accent">Use working copy</button>'}`);
    $('#operator-cancel').onclick=closeModal;
    $('#operator-proceed')?.addEventListener('click',()=>{modalDismiss=null;closeModal();resolve('copy');});
  });
}

function transformCommandDialog(operatorId){
 const adjustable=operators.list().find(op=>op.id===operatorId)?.available;
 if(!adjustable)return notify('No transform is available to adjust.');
 const target=operatorId==='history.adjust_transform'?editor.root.getObjectByProperty('uuid',editor.journal.entries.at(-1).id):editor.selected;
 modal(operatorId==='history.adjust_transform'?'Adjust Last Transform':'Transform Object',`<label class="field-label">Property<select id="operator-transform-kind"><option value="position">Position (m)</option><option value="rotation">Rotation (degrees)</option><option value="scale">Scale</option></select></label><label class="field-label">Axis<select id="operator-transform-axis"><option>x</option><option>y</option><option>z</option></select></label><label class="field-label">Value<input id="operator-transform-value" type="number" step="0.01" value="${target.position.x}"></label>`,`<button id="operator-transform-apply" class="button accent">Apply</button>`);
 const update=()=>{const kind=$('#operator-transform-kind').value,axis=$('#operator-transform-axis').value;$('#operator-transform-value').value=target[kind][axis]*(kind==='rotation'?180/Math.PI:1);};$('#operator-transform-kind').onchange=update;$('#operator-transform-axis').onchange=update;
 $('#operator-transform-apply').onclick=()=>{const props={kind:$('#operator-transform-kind').value,axis:$('#operator-transform-axis').value,value:Number($('#operator-transform-value').value)};closeModal();attempt(()=>operators.run(operatorId,props));};
}
